import 'server-only'

function required(name: string) {
  const value = process.env[name]
  if (!value) throw new Error(`Missing environment variable: ${name}`)
  return value
}

export const env = {
  databaseUrl: required('DATABASE_URL'),
  authSecret: required('AUTH_SECRET'),
  appUrl: required('APP_URL'),
}

const locales = ['en', 'id', 'nl'] as const

export function generateStaticParams() {
  return locales.map((lang) => ({ lang }))
}

export default async function Layout({ children, params }) {
  const { lang } = await params
  if (!locales.includes(lang)) notFound()
  return <html lang={lang}><body>{children}</body></html>
}

import { cookies } from 'next/headers'

export async function DensityPreference() {
  const store = await cookies()
  const density = store.get('density')?.value ?? 'comfortable'
  return <span>Density: {density}</span>
}

import 'server-only'

export async function getProjectSummary(userId: string, projectId: string) {
  const project = await db.query.projects.findFirst({
    where: and(eq(projects.id, projectId), eq(projects.ownerId, userId)),
    columns: { id: true, name: true, updatedAt: true },
  })
  if (!project) return null
  return project
}

export async function register() {
  if (process.env.NEXT_RUNTIME === 'nodejs') {
    await import('./instrumentation-node')
  }

  if (process.env.NEXT_RUNTIME === 'edge') {
    await import('./instrumentation-edge')
  }
}
